from lib import *
S = SS('v19')
steps = [
    step("取模 vs 一致性哈希环。100000 个 key、10 个节点,加 1 个节点(10 → 11)和去掉 1 个节点(10 → 9),理想值是 1/11 ≈ 9.1% 和 1/10 = 10%。取模:加一个节点归属变了 90.8%,去掉一个变了 89.8%。一致性哈希环 vnodes = 1:变了 12.1% 和 21.8%,最忙节点是平均的 2.26 倍;vnodes = 10:7.2% 和 13.7%,不均 1.44;vnodes = 100:8.2% 和 10.2%,不均 1.20;vnodes = 1000:9.4% 和 9.9%,不均 1.05。取模几乎所有 key 都要搬;环只搬 1/N 左右;虚拟节点越多越均匀,越接近理想值。", t=tl(S(1)), mark=lidx(S(1), '取模'), done=[i for i, l in enumerate(S(1)) if l.strip().startswith('一致性哈希环')], b=bars([['取模:加 1 个节点变了 %', 90.8, '90.8%'], ['环 vnodes=1:变了 %', 12.1, '12.1%'], ['环 vnodes=1000:变了 %', 9.4, '9.4%'], ['环 vnodes=1:负载不均', 2.26, '2.26'], ['环 vnodes=1000:负载不均', 1.05, '1.05']], 90.8, mark=[0], cur=[1, 3], done=[2, 4]), kv=KV([['取模', '加或去掉一个节点,约 90% 的 key 搬家'], ['一致性哈希环', '约 1/N(9% 到 10%)'], ['vnodes', '1 → 1000:不均 2.26 → 1.05']], ['一致性哈希环'])),
    step("nginx 的真实表现。4 个后端 A、B、C、D,2000 个请求,加 E(reload 成 5 个后端)、再去掉 D(reload 成 A、B、C)。普通 hash $http_x_key:4 个后端时各收到 499 / 501 / 501 / 499;加 E 后归属变了 79.7%,其中只有 26% 搬到了 E(其余在老节点之间乱搬);去掉 D 后变了 74.0%,原本不在 D 上却被搬走的 key 有 980 个。hash $http_x_key consistent(ketama):各收到 477 / 535 / 458 / 530;加 E 后变了 23.8%,100% 搬到了 E;去掉 D 后变了 26.5%,原本不在 D 上被搬走的 key 是 0 个。理想值是 20% 和约 25%。", t=tl(S(2)), mark=lidx(S(2), '普通 hash'), done=lidx(S(2), 'consistent(ketama)'), b=bars([['普通 hash:加 E 变了 %', 79.7, '79.7%'], ['consistent:加 E 变了 %', 23.8, '23.8%'], ['普通 hash:去掉 D 误搬', 980, '980 个'], ['consistent:去掉 D 误搬', 0, '0 个']], 980, mark=[0, 2], done=[1, 3]), kv=KV([['普通 hash 加 E', '79.7% 变了,只有 26% 搬到 E'], ['consistent 加 E', '23.8% 变了,100% 搬到 E'], ['去掉 D', '普通 980 个误搬,consistent 0 个']], ['consistent 加 E'])),
    step("有权重的节点和热点。手写的环上,节点 n0 权重 3、其余 9 个节点权重 1(vnodes = 100 × 权重),100000 个均匀的 key:n0 分到 24.5%(理论 25.0%),其余 9 个节点各 7.7% 到 10.4%。再让一个热点 key 占总流量的 10%(其余均匀):热点 key 落在 n0 上,n0 承担全部流量的 32.0%,按权重本该是 25.0%。一致性哈希只管 key 的归属,不管 key 的热度;热点 key 落到谁头上,谁就比份额多承担一块。", t=tl(S(3)), mark=lidx(S(3), '热点'), done=lidx(S(3), '按权重分'), b=bars([['n0 按权重应得 %', 25.0, '25.0%'], ['n0 实际分到 key %', 24.5, '24.5%'], ['n0 加热点后负载 %', 32.0, '32.0%']], 32, done=[0, 1], mark=[2]), kv=KV([['权重 3 的 n0', 'key 归属 24.5%(理论 25.0%)'], ['热点 key 10% 流量', 'n0 的负载升到 32.0%']], ['热点 key 10% 流量'])),
]
